ssName() { return "BUTTON"; }#endif	//------------------------------------------------------------------------------------	// Stream I/O protocol support.	//------------------------------------------------------------------------------------	virtual void ReadFields(CStream_AC* aStream);	virtual void WriteFields(CStream_AC* aStream) const;	virtual void DoPostCreate(TDocument* itsDocument);	virtual void DoEvent(EventNumber eventNumber, TEventHandler* source, TEvent* event);		// If the hit is mButtonHit then flash the button provided you didn't hit        // yourself.	virtual void CreateControl();		// Used to create a new control, calls NewControl to create the control.		// Overridden to call SetDefaultOutline to fix up the control.	TAdorner* FindRRectAdorner();		// Finds a TRRectAdorner or TCompatibilityAdorner with RRect		// that gets attached to default buttons..	bool SupportsDefaultOutline();		// Whether the control supports drawing its own default outline.		// If not, we just draw it ourselves using an adorner.	virtual bool IsDefault();		// Whether this button is a default button.	virtual void SetDefaultState(bool isDefault, bool redraw);		// Sets the "default" outline state for this button,		// which affects the inset, pen size and round rect adornment.		// Call this to change the default outline.	virtual void SetDefaultOutline();		// After the control is created, this determines whether the button has a default		// outline and fixes up the control so it is displayed and handled correctly.	virtual CControl_AC* DoMakeControl(WindowRef			theWindow,									   const CRect_AC&		boundsRect,									   bool					isVisible,									   bool					isEnabled,									   const CStr255_AC&	itsTitle);		// Factory method creates the control.#if qCarbon	virtual void InvalidateCoordinates();		// Override to immediately update the location for default buttons.#endif	//------------------------------------------------------------------------------------	// Event Handling	//------------------------------------------------------------------------------------#if qMSWindows	virtual long HandleWindowsEvent(HWND hwnd, UINT message, WPARAM wParam, LPARAM lParam);#endif	//------------------------------------------------------------------------------------	// data members	//------------------------------------------------------------------------------------public:	ResNumber	fStrListID;						// button's label:	STR# rsrc id	short		fIndex;							//					index into STR#};#if qAppearance//----------------------------------------------------------------------------------------// TIconPushButton//----------------------------------------------------------------------------------------class EXPORT_MA TIconPushButton : public TButton// Mimics a typical toolbox button with a color icon to the left or right of the label.// Note: Requires the Appearance Manager (i.e., there is no emulation support).// The icon and its positioning can only be set at control creation time; therefore,// there are no accessors/manipulators provided for changing them.{	MA_DECLARE_CLASS;public:	TIconPushButton(const CViewPoint&	itsLocation = gZeroVPt,					const CViewPoint&	itsSize = gZeroVPt,					SizeDeterminer		itsHSizeDet = sizeVariable,					SizeDeterminer		itsVSizeDet = sizeVariable,					const CStr255_AC&	itsTitle = gEmptyString,					bool				isDefault = false,					ResNumber			itsIconID = kNoResource_AC,					bool				positionLeftOfLabel = true);		// Initializes the button, setting the fDefaultChoice field to mButtonHit.	TIconPushButton(const TIconPushButton& inButton);		// Copy Constructor	virtual ~TIconPushButton();		// Destructor	//------------------------------------------------------------------------------------	// Standard signature support.	//------------------------------------------------------------------------------------	virtual IDType GetStandardSignature() const;		// Returns this class's standard signature.	//------------------------------------------------------------------------------------	// Stream I/O protocol support.	//------------------------------------------------------------------------------------	virtual void ReadFields(CStream_AC* aStream);	virtual void WriteFields(CStream_AC* aStream) const;	virtual CControl_AC* DoMakeControl(WindowRef			theWindow,									   const CRect_AC&		boundsRect,									   bool					isVisible,									   bool					isEnabled,									   const CStr255_AC&	itsTitle);		// Factory method creates the control.	//------------------------------------------------------------------------------------	// data members	//------------------------------------------------------------------------------------protected:	ResNumber	fIconID;						// cicn resource ID	bool		fPositionLeftOfLabel;			// icon position: right or left of label};#endif // qAppearanceEXPORT_MA void InitUButton();#if qAppearanceEXPORT_MA void InitUIconPushButton();#endif#endif // __UBUTTON__/*	Historical Change Record:		----- R11 -----		06/26/96	Install release marker.  Scope many globals.  Change TRUE/FALSE/NULL.		04/17/96	InitUButton		04/15/96	Phase 1 of View Breakup changes		----- Release 10 -----*/